139	    /// Opens the relay session first, then hands the session a client that speaks
140	    /// over it. `start()` only begins asking central for a session — nothing has
141	    /// reached the robot yet, and the control channel's own deadline is what
142	    /// bounds the wait if it never answers.
143	    private func connectRemotely(to robot: CentralRobot) {
144	        showsRemoteRobots = false
145	        remoteLink?.stop()
146	        let link = RemoteRobotLink(
147	            robot: robot,
148	            relay: CentralRelayClient { [hfAccount] in await hfAccount.currentToken() }
149	        )
150	        remoteLink = link
151	        link.start()
152	        tab = .robot
153	        Task { await session.connect(using: link.client) }
154	    }
