3	/// The one place a live view of the robot is mounted.
4	///
5	/// There is deliberately no second instance anywhere: `RobotSceneView` hands the
6	/// scene's root entity to `RealityView`, and an entity has exactly one parent, so
7	/// a second viewport would silently steal the robot from the first.
8	struct ViewportView: View {
9	    let model: ViewportModel
10	    /// The robot reports no camera at all on a wired unit — then there is nothing
11	    /// to switch between and the control is hidden rather than disabled.
12	    let offersCamera: Bool
13	    /// Which safe-area insets the backdrop may bleed into. The floating tab bar is
14	    /// glass and renders whatever lies under it, so the inset it occupies — bottom
15	    /// on iPhone, top on iPad — has to stay unpainted, or the bar goes dark on this
16	    /// tab alone, a frame behind the switch. Sideways is always safe; upwards only
17	    /// where a bar pinned to match is waiting for the black.
18	    var backdropEdges: Edge.Set = .horizontal
19	
20	    var body: some View {
21	        content
22	            .frame(maxWidth: .infinity, maxHeight: .infinity)
23	            // One backdrop for both contents, so the chrome above has a single thing to
24	            // be legible against. The camera already letterboxes onto black; the 3D scene
25	            // otherwise takes the system background and turns white in the light
26	            // appearance, which is what left the title unreadable.
27	            // `background(_:)` would otherwise default to `ignoresSafeAreaEdges: .all`.
28	            .background(Color.black, ignoresSafeAreaEdges: backdropEdges)
29	            .overlay(alignment: .topLeading) { chrome }
30	    }
31	
32	    /// Every floating control hugs the leading edge: on iPad the tab bar floats
33	    /// over the top centre, and anything trailing-aligned ends up underneath it.
34	    private var chrome: some View {
35	        HStack(spacing: 12) {
36	            switcher
37	            contentControls
38	        }
39	        .padding(12)
40	    }
41	
42	    @ViewBuilder
43	    private var contentControls: some View {
44	        switch model.content {
45	        case .scene:
46	            if let sceneModel = model.sceneModel {
47	                SceneOptionsMenu(model: sceneModel)
48	            }
49	        case .camera:
50	            if let session = model.cameraSession {
51	                CameraMicButton(session: session)
52	            }
53	        }
54	    }
