import AppKit
import CoreGraphics
import Foundation

// crop.swift <in> <out> <y> <height> [gain]
// Crops a horizontal strip and optionally multiplies luminance, so text that is
// nearly the same colour as its backdrop becomes visible.
let args = CommandLine.arguments
guard args.count >= 5,
      let src = NSImage(contentsOfFile: args[1])?
      .cgImage(forProposedRect: nil, context: nil, hints: nil),
      let y = Int(args[3]), let h = Int(args[4])
else {
    FileHandle.standardError.write(Data("usage: crop <in> <out> <y> <h> [gain]\n".utf8))
    exit(1)
}
let gain = args.count > 5 ? Double(args[5]) ?? 1 : 1

guard let strip = src.cropping(to: CGRect(x: 0, y: y, width: src.width, height: h)) else { exit(1) }

let w = strip.width, sh = strip.height
var pixels = [UInt8](repeating: 0, count: w * sh * 4)
guard let ctx = CGContext(
    data: &pixels, width: w, height: sh, bitsPerComponent: 8, bytesPerRow: w * 4,
    space: CGColorSpaceCreateDeviceRGB(),
    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
) else { exit(1) }
ctx.draw(strip, in: CGRect(x: 0, y: 0, width: w, height: sh))

if gain != 1 {
    for i in stride(from: 0, to: pixels.count, by: 4) {
        for c in 0 ..< 3 {
            pixels[i + c] = UInt8(min(255, Double(pixels[i + c]) * gain))
        }
    }
}

